def count_Fac(n):
    def prime_factors(n):
        factors = set()
        i = 2
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                factors.add(i)
        if n > 1:
            factors.add(n)
        return factors

    def power_of_prime(factors):
        counts = {}
        for factor in factors:
            counts[factor] = counts.get(factor, 0) + 1
        return counts

    factors = prime_factors(n)
    return len(power_of_prime(factors))

