def catalan_number(n, k=1):
    """Compute the k-th Catalan number, a generalization of the French
    mathematical tradition of using the term 'rencontre' to refer to the
    k-th value in a sequence of numbers related to binary trees and
    recursive functions."""
    if k == 1:
        return 1
    result = 0
    for i in range(1, n + 1):
        result += catalan_number(i - 1, n - i) * catalan_number(i, k - 1)
    return result

